@Composable fun vsoftT(fa:String,en:String,ar:String=fa):String=when(LocalVsoftLanguage.current){"en"->en;"ar"->ar;else->fa}
object VsoftTint { val blue=Color(0xFF007AFF);val green=Color(0xFF34C759);val orange=Color(0xFFFF9500);val purple=Color(0xFFAF52DE);val red=Color(0xFFFF3B30);val teal=Color(0xFF30B0C7);val gray=Color(0xFF8E8E93) }
@Composable fun VsoftDateHeader(title:String,amount:Long?=null){val c=VsoftTheme.colors;Row(Modifier.fillMaxWidth().padding(start=16.dp,end=16.dp,top=20.dp,bottom=8.dp),verticalAlignment=Alignment.CenterVertically){Text(title,style=MaterialTheme.typography.bodySmall.copy(fontWeight=FontWeight.SemiBold),color=c.labelSecondary,modifier=Modifier.weight(1f));if(amount!=null)VsoftAmountText(amount,style=MaterialTheme.typography.bodySmall,color=if(amount>=0)c.income else c.expense,prefix=if(amount>0)"+" else "")}}
@Composable fun VsoftTransactionRow(transaction:Transaction,modifier:Modifier=Modifier,showDate:Boolean=false,onClick:(()->Unit)?=null){val c=VsoftTheme.colors;val income=transaction.type=="income";val tint=if(income)c.income else c.expense;val subtitle=listOf(transaction.description,transaction.card,if(showDate)transaction.date else "").filter{it.isNotBlank()}.joinToString(" • ");Row((if(onClick!=null)modifier.vsoftTap(onClick=onClick)else modifier).fillMaxWidth().padding(horizontal=16.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically){VsoftSoftIcon(if(income)Icons.Filled.ArrowDownward else Icons.Filled.ArrowUpward,tint);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(transaction.category.ifBlank{"—"},style=MaterialTheme.typography.bodyLarge,maxLines=1,overflow=TextOverflow.Ellipsis);if(subtitle.isNotBlank())Text(subtitle,style=MaterialTheme.typography.bodySmall,color=c.labelSecondary,maxLines=1,overflow=TextOverflow.Ellipsis)};Spacer(Modifier.width(8.dp));VsoftAmountText(transaction.amount,color=tint,prefix=if(income)"+" else "−",fontWeight=FontWeight.SemiBold)}}
@Composable fun VsoftWorkRow(work:WorkDay,modifier:Modifier=Modifier,onClick:(()->Unit)?=null){val c=VsoftTheme.colors;val hours=calculateHours(work.start,work.end);val subtitle=listOf(work.start+"–"+work.end+" • "+String.format(Locale.US,"%.1f",hours)+vsoftT(" ساعت"," h"," ساعة"),work.person).filter{it.isNotBlank()}.joinToString(" • ");Row((if(onClick!=null)modifier.vsoftTap(onClick=onClick)else modifier).fillMaxWidth().padding(horizontal=16.dp,vertical=10.dp),verticalAlignment=Alignment.CenterVertically){VsoftSoftIcon(Icons.Filled.Work,c.accent);Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(work.place.ifBlank{vsoftT("محل کار ثبت نشده","No workplace","لم يتم تحديد مكان العمل")},style=MaterialTheme.typography.bodyLarge,maxLines=1,overflow=TextOverflow.Ellipsis);Text(subtitle,style=MaterialTheme.typography.bodySmall,color=c.labelSecondary,maxLines=1,overflow=TextOverflow.Ellipsis)};if(work.income>0){Spacer(Modifier.width(8.dp));VsoftAmountText(work.income,color=c.income,prefix="+",fontWeight=FontWeight.SemiBold)}}}
@Composable fun VsoftMiniCard(card:BankCard,balance:Long,modifier:Modifier=Modifier){val (bankColor,_)=bankCardColors(card.bank);val last4=card.last4.ifBlank{card.cardNumber.takeLast(4)};Surface(modifier.width(210.dp).height(112.dp),shape=RoundedCornerShape(16.dp),color=bankColor){Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.SpaceBetween){Row(verticalAlignment=Alignment.CenterVertically){Text(card.bank,color=Color.White,style=MaterialTheme.typography.titleSmall,maxLines=1,overflow=TextOverflow.Ellipsis,modifier=Modifier.weight(1f));if(last4.isNotBlank())CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr){Text("•••• $last4",color=Color.White.copy(alpha=.8f),style=MaterialTheme.typography.bodySmall)}};VsoftAmountText(balance,color=Color.White,style=MaterialTheme.typography.titleLarge.copy(fontSize=20.sp))}}}
@Composable fun VsoftFilterChip(label:String,selected:Boolean,onClick:()->Unit,modifier:Modifier=Modifier){val c=VsoftTheme.colors;val bg by animateColorAsState(if(selected)c.accent else c.surface,tween(150),label="chip_bg");Box(modifier.vsoftTap(onClick=onClick).clip(CircleShape).background(bg).padding(horizontal=14.dp,vertical=8.dp),contentAlignment=Alignment.Center){Text(label,style=MaterialTheme.typography.labelMedium,color=if(selected)Color.White else c.label,maxLines=1)}}
@Composable fun VsoftSelectField(label:String,value:String,placeholder:String,onClick:()->Unit,modifier:Modifier=Modifier,leadingIcon:ImageVector?=null,showTrailing:Boolean=true){val c=VsoftTheme.colors;Column(modifier.fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(6.dp)){Text(label,style=MaterialTheme.typography.bodySmall,color=c.labelSecondary,modifier=Modifier.padding(horizontal=4.dp));Row(Modifier.fillMaxWidth().height(52.dp).vsoftTap(onClick=onClick).clip(VsoftShapes.control).background(c.fieldBackground).padding(horizontal=14.dp),verticalAlignment=Alignment.CenterVertically){if(leadingIcon!=null){Icon(leadingIcon,null,tint=c.labelSecondary,modifier=Modifier.size(20.dp));Spacer(Modifier.width(10.dp))};Text(if(value.isBlank())placeholder else value,style=MaterialTheme.typography.bodyLarge,color=if(value.isBlank())c.labelTertiary else c.label,maxLines=1,overflow=TextOverflow.Ellipsis,modifier=Modifier.weight(1f));if(showTrailing)Icon(Icons.Filled.UnfoldMore,null,tint=c.labelTertiary,modifier=Modifier.size(20.dp))}}}
@Composable fun VsoftMenuField(label:String,value:String,placeholder:String,modifier:Modifier=Modifier,leadingIcon:ImageVector?=null,menu:@Composable (dismiss:()->Unit)->Unit){var open by remember{mutableStateOf(false)};Box(modifier.fillMaxWidth()){VsoftSelectField(label,value,placeholder,{open=true},leadingIcon=leadingIcon);DropdownMenu(expanded=open,onDismissRequest={open=false}){menu{open=false}}}}
data class VsoftAction(val label:String,val icon:ImageVector,val destructive:Boolean=false,val onClick:()->Unit)
@Composable fun VsoftActionSheet(title:String?,actions:List<VsoftAction>,onDismiss:()->Unit){val c=VsoftTheme.colors;VsoftFormSheet(onDismiss=onDismiss,title=title){Column(Modifier.padding(horizontal=16.dp).padding(bottom=16.dp)){Surface(shape=VsoftShapes.card,color=c.fieldBackground,modifier=Modifier.fillMaxWidth()){Column{actions.forEachIndexed{i,a->VsoftGroupedRow(title=a.label,titleColor=if(a.destructive)c.expense else c.label,trailing={Icon(a.icon,null,tint=if(a.destructive)c.expense else c.accent,modifier=Modifier.size(22.dp))},onClick={onDismiss();a.onClick()});if(i<actions.lastIndex)VsoftGroupedDivider()}}}}}
@Composable private fun VsoftChartBar(fraction:Float,color:Color,alpha:Float){Box(Modifier.width(9.dp).fillMaxHeight(fraction.coerceIn(.02f,1f)).clip(RoundedCornerShape(topStart=3.dp,topEnd=3.dp)).background(color.copy(alpha=alpha)))}
@Composable fun VsoftMonthlyChart(monthly:List<Triple<String,Long,Long>>,modifier:Modifier=Modifier){val c=VsoftTheme.colors;var selected by remember(monthly){mutableStateOf(monthly.lastOrNull()?.first.orEmpty())};val point=monthly.firstOrNull{it.first==selected}?:monthly.lastOrNull();val max=monthly.flatMap{listOf(it.second,it.third)}.maxOrNull()?.coerceAtLeast(1L)?:1L;VsoftCardSurface(modifier){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text(vsoftT("روند ۶ ماهه","6-month trend","اتجاه 6 أشهر"),style=MaterialTheme.typography.titleSmall,modifier=Modifier.weight(1f));Text(vsoftT("درآمد","Income","الدخل"),color=c.income,style=MaterialTheme.typography.bodySmall);Spacer(Modifier.width(8.dp));Text(vsoftT("هزینه","Expense","المصروف"),color=c.expense,style=MaterialTheme.typography.bodySmall)};Row(Modifier.fillMaxWidth().height(150.dp),horizontalArrangement=Arrangement.spacedBy(6.dp)){monthly.forEach{m->val chosen=m.first==point?.first;Column(Modifier.weight(1f).fillMaxHeight().vsoftTap{selected=m.first},horizontalAlignment=Alignment.CenterHorizontally){Row(Modifier.weight(1f).fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(3.dp,Alignment.CenterHorizontally),verticalAlignment=Alignment.Bottom){VsoftChartBar(if(m.second>0)m.second.toFloat()/max.toFloat() else 0f,c.income,if(chosen)1f else .45f);VsoftChartBar(if(m.third>0)m.third.toFloat()/max.toFloat() else 0f,c.expense,if(chosen)1f else .45f)};Spacer(Modifier.height(6.dp));Text(m.first.substringAfter('/'),style=MaterialTheme.typography.labelSmall,color=if(chosen)c.label else c.labelTertiary,textAlign=TextAlign.Center)}};if(point!=null)Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(12.dp)){Column(Modifier.weight(1f)){Text(vsoftT("درآمد","Income","الدخل")+" • "+point.first,style=MaterialTheme.typography.bodySmall,color=c.labelSecondary);VsoftAmountText(point.second,color=c.income,fontWeight=FontWeight.SemiBold)};Column(Modifier.weight(1f)){Text(vsoftT("هزینه","Expense","المصروف")+" • "+point.first,style=MaterialTheme.typography.bodySmall,color=c.labelSecondary);VsoftAmountText(point.third,color=c.expense,fontWeight=FontWeight.SemiBold)}}}}}
